import re

_LOG_LINE_RE = re.compile(r'^(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}) \[(ERROR|WARN|INFO|DEBUG)\] (.*)$')
_KEY_VALUE_RE = re.compile(r'(?:^|\s)([A-Za-z0-9]+)=')


def parse_logs(logs):
    parsed = []
    for line in logs:
        if not isinstance(line, str):
            continue
        match = _LOG_LINE_RE.match(line)
        if match is None:
            continue
        timestamp = match.group(1)
        level = match.group(2)
        rest = match.group(3)

        kv = {}
        message = rest.strip()
        first_key = _KEY_VALUE_RE.search(rest)
        if first_key is not None:
            section = rest[first_key.start(1):]
            key_matches = list(_KEY_VALUE_RE.finditer(section))
            for i, key_match in enumerate(key_matches):
                key = key_match.group(1)
                value_start = key_match.end()
                if i + 1 < len(key_matches):
                    value_end = key_matches[i + 1].start(1)
                else:
                    value_end = len(section)
                kv[key] = section[value_start:value_end].strip()
            message = rest[:first_key.start(1)].strip()

        parsed.append({
            'timestamp': timestamp,
            'level': level,
            'message': message,
            'kv': kv,
        })
    return parsed
